-- ============================================================
-- Migração — Perfil e PermissaoPerfil (catálogo global de perfis
-- + matriz de permissões editável pelo Administrador Contrata+)
-- Cria as tabelas e faz o seed com o que já existe hoje em
-- lib/permissoes.ts — nada muda de comportamento até alguém
-- editar algo pela tela nova.
-- ============================================================

BEGIN;

CREATE TABLE IF NOT EXISTS perfil (
  id            TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
  nome          TEXT NOT NULL UNIQUE,
  descricao     TEXT,
  sistemico     BOOLEAN NOT NULL DEFAULT false,
  ativo         BOOLEAN NOT NULL DEFAULT true,
  criado_em     TIMESTAMPTZ NOT NULL DEFAULT now(),
  atualizado_em TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS permissao_perfil (
  id         TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
  id_perfil  TEXT NOT NULL REFERENCES perfil(id) ON DELETE CASCADE,
  modulo     TEXT NOT NULL,
  processo   TEXT NOT NULL,
  tipo       TEXT NOT NULL,
  concedido  BOOLEAN NOT NULL DEFAULT false,
  UNIQUE (id_perfil, modulo, processo)
);
CREATE INDEX IF NOT EXISTS idx_permissao_perfil_id_perfil ON permissao_perfil(id_perfil);

-- ── Seed: os 9 perfis que já existem hoje ──────────────────

-- ── Seed: a matriz completa (perfil x módulo x processo) ───
-- "Admin" recebe concedido=true em tudo, espelhando o bypass
-- total que ele já tinha no código atual (perfil === 'Admin').


COMMIT;

-- ============================================================
-- Conferência
-- ============================================================
SELECT (SELECT COUNT(*) FROM perfil) AS total_perfis, (SELECT COUNT(*) FROM permissao_perfil) AS total_linhas_matriz;